import{_ as r,o as a,c as t,ag as o}from"./chunks/framework.D5hoimZQ.js";const p=JSON.parse('{"title":"🔬 科学快报 | 2026年9月27日（事后重建版）","description":"","frontmatter":{"sidebar":true},"headers":[],"relativePath":"science-log/src/reconstructed/2026-09-27.md","filePath":"science-log/src/reconstructed/2026-09-27.md"}'),n={name:"science-log/src/reconstructed/2026-09-27.md"};function s(i,e,l,c,h,d){return a(),t("div",null,[...e[0]||(e[0]=[o('<h1 id="🔬-科学快报-2026年9月27日-事后重建版" tabindex="-1">🔬 科学快报 | 2026年9月27日（事后重建版） <a class="header-anchor" href="#🔬-科学快报-2026年9月27日-事后重建版" aria-label="Permalink to &quot;🔬 科学快报 | 2026年9月27日（事后重建版）&quot;">​</a></h1><blockquote><p>⚠️ <strong>事后重建版</strong>：本文件<strong>不是</strong>当日发布原文。由 2026-11-05 依 arXiv / CrossRef <strong>按发布日期回溯检索</strong>生成，选题与排序均为事后判定，<strong>不代表历史原貌</strong>。 说明：2026-09-27 为<strong>周日</strong>，Nature（0028-0836）/ Science 系（10.1126）/ PNAS（0027-8424）的 CrossRef 当日命中均为 <strong>0 条</strong>（期刊周末不刊出）。故科学 5 篇取自**最近的刊出日 2026-09-25（周五）**的研究论文（Science Advances / PNAS）；AI 5 篇取自当日 arXiv cs.AI 提交（submittedDate 命中 40 篇）。选题与排序为事后判定，<strong>不代表历史原貌</strong>。 取证：CrossRef（Nature 0028-0836 / Science 10.1126 / PNAS 0027-8424）+ arXiv 日期区间 <code>[202609270000 TO 202609272359]</code>（cs.AI）｜ 重建日：2026-11-05</p></blockquote><h2 id="🔬-科学前沿" tabindex="-1">🔬 科学前沿 <a class="header-anchor" href="#🔬-科学前沿" aria-label="Permalink to &quot;🔬 科学前沿&quot;">​</a></h2><h3 id="🌍-地核形成即可解释地幔的强亲铁元素过剩-无需「晚期薄层」" tabindex="-1">🌍 地核形成即可解释地幔的强亲铁元素过剩，无需「晚期薄层」 <a class="header-anchor" href="#🌍-地核形成即可解释地幔的强亲铁元素过剩-无需「晚期薄层」" aria-label="Permalink to &quot;🌍 地核形成即可解释地幔的强亲铁元素过剩，无需「晚期薄层」&quot;">​</a></h3><p><strong>Core formation resolves Earth&#39;s siderophile excess without a late veneer</strong><em>Science Advances (2026)</em></p><p>强亲铁元素（HSE）对金属有高亲和性，理论上应在地核形成时被大量带入地核、在地幔中极度亏损，但实测地幔丰度远高于低压低温分配实验的预测，且各 HSE 呈球粒陨石式的相对比例。传统解释诉诸「晚期薄层（late veneer）」——即地核形成后再落入一批球粒陨石。作者用激光加热金刚石压腔，在直接对应早期地球岩浆洋的温压条件下测定铼、锇、铱、钯、金五种 HSE 的金属—硅酸盐分配系数，发现分配系数随温度显著下降；多阶段吸积模型据此可复现地幔的 HSE 丰度与比值，<strong>无需引入晚期薄层</strong>。这为「挥发分主要由早期吸积与分异过程带到年轻地球」提供了支持。DOI: <a href="https://doi.org/10.1126/sciadv.aef0411" target="_blank" rel="noreferrer">10.1126/sciadv.aef0411</a></p><h3 id="🔬-电子叠层成像在原子尺度定量金属氢化物中的氢" tabindex="-1">🔬 电子叠层成像在原子尺度定量金属氢化物中的氢 <a class="header-anchor" href="#🔬-电子叠层成像在原子尺度定量金属氢化物中的氢" aria-label="Permalink to &quot;🔬 电子叠层成像在原子尺度定量金属氢化物中的氢&quot;">​</a></h3><p><strong>Atomic-scale quantification of hydrogen in metal hydrides by electron ptychography</strong><em>Science Advances (2026)</em></p><p>氢是最轻的元素，电子散射极弱、迁移性高，常规透射电镜难以定位其原子占位，导致氢在材料中的空间分布长期「不可见」。作者以能量过滤多层电子叠层成像（MEP）对一种复杂高熵合金氢化物成像，分辨出此前无法获取的结构细节：皮米级氢位移与显著的三维不均匀性。统计分析还发现，氢的引入<strong>意外抑制了原始高熵合金中固有的晶格畸变</strong>。该平台为从氢脆、储氢到电子相变等涉及氢的现象提供了原子级定量成像手段。DOI: <a href="https://doi.org/10.1126/sciadv.aed5872" target="_blank" rel="noreferrer">10.1126/sciadv.aed5872</a></p><h3 id="🌱-合成-fls2-受体二聚体提升植物先天免疫" tabindex="-1">🌱 合成 FLS2 受体二聚体提升植物先天免疫 <a class="header-anchor" href="#🌱-合成-fls2-受体二聚体提升植物先天免疫" aria-label="Permalink to &quot;🌱 合成 FLS2 受体二聚体提升植物先天免疫&quot;">​</a></h3><p><strong>Synthetic FLS2 receptor oligomer boosts plant innate immunity</strong><em>Science Advances (2026)</em></p><p>细胞表面受体的逐步组装与寡聚化是免疫激活与周转的关键，但植物免疫中「动态、时空受控的组装如何带来快速且持久的信号」一直不清楚。作者用合成工程手段精确控制拟南芥 FLS2 受体的寡聚状态，结合单颗粒成像与定量标定，发现 FLS2 从以单体为主的静息态、在激活时转为瞬时的同源二聚。人工构造的<strong>同源二聚</strong>显著增强防御反应，同时避开「高阶组装」——后者会阻碍受体动态补充、损害持久免疫。这提示通过精确控制受体组装，可同时兼顾即时激活与长效信号，为工程化耐久植物免疫提供策略。DOI: <a href="https://doi.org/10.1126/sciadv.aeg6872" target="_blank" rel="noreferrer">10.1126/sciadv.aeg6872</a></p><h3 id="🧠-丘脑—前额叶突触减弱是青春期-nmdar-功能低下致短时记忆缺损的机制" tabindex="-1">🧠 丘脑—前额叶突触减弱是青春期 NMDAR 功能低下致短时记忆缺损的机制 <a class="header-anchor" href="#🧠-丘脑—前额叶突触减弱是青春期-nmdar-功能低下致短时记忆缺损的机制" aria-label="Permalink to &quot;🧠 丘脑—前额叶突触减弱是青春期 NMDAR 功能低下致短时记忆缺损的机制&quot;">​</a></h3><p><strong>Thalamofrontal synaptic weakening underlies short-term memory deficits from adolescent NMDAR hypofunction</strong><em>Science Advances (2026)</em></p><p>丘脑—前额叶（TF）连接受损是精神分裂症最一致的环路异常之一，并与短时记忆（STM）缺损相关，但其生物学机制不明。作者让小鼠在青春期反复接受 NMDAR 拮抗（氯胺酮），发现 STM 缺损伴随<strong>内侧背侧丘脑（MD）→背内侧前额叶（dmPFC）突触的释放概率下降与短时程抑制减弱</strong>，而皮质—皮质突触、内在兴奋性与大体超微结构均无明显变化。这些突触前缺陷叠加 dmPFC 方向选择性群体编码减弱与延迟交替作业受损；用化学遗传学<strong>增强 MD→dmPFC 投射可同时恢复神经选择性与行为</strong>。研究给出一个投射特异性的突触前机制。DOI: <a href="https://doi.org/10.1126/sciadv.aee2152" target="_blank" rel="noreferrer">10.1126/sciadv.aee2152</a></p><h3 id="🌀-耗散光学孤子自组织中的瞬态混沌" tabindex="-1">🌀 耗散光学孤子自组织中的瞬态混沌 <a class="header-anchor" href="#🌀-耗散光学孤子自组织中的瞬态混沌" aria-label="Permalink to &quot;🌀 耗散光学孤子自组织中的瞬态混沌&quot;">​</a></h3><p><strong>Transient chaos in the self-organization of dissipative optical solitons</strong><em>PNAS (2026)</em></p><p>瞬态混沌是非线性系统中复杂动力学的标志，由混沌鞍控制，表现为短暂而丰富的混沌行为后骤然跃迁到稳定吸引子，但这类不可预测、不可重复的过程难以实时捕捉与定量刻画。作者在锁模光纤激光器中实验演示了耗散光学孤子自组织过程中的瞬态混沌：通过单次测量重建相空间轨迹，量化可确认其非吸引混沌集之确定性的关键动力学不变量。实验与数值结果揭示该复杂性源于不稳定多脉冲复合体内的耦合非线性相互作用，并在此混沌瞬态中鉴定出极高振幅的<strong>光学怪波（rogue wave）</strong>，在光学混沌与锁模相干之间架起概念桥梁。DOI: <a href="https://doi.org/10.1073/pnas.2624826123" target="_blank" rel="noreferrer">10.1073/pnas.2624826123</a></p><h2 id="🤖-ai-前沿" tabindex="-1">🤖 AI 前沿 <a class="header-anchor" href="#🤖-ai-前沿" aria-label="Permalink to &quot;🤖 AI 前沿&quot;">​</a></h2><h3 id="🎯-uopd-面向多轮智能体在线策略蒸馏的不确定性感知干预" tabindex="-1">🎯 UOPD：面向多轮智能体在线策略蒸馏的不确定性感知干预 <a class="header-anchor" href="#🎯-uopd-面向多轮智能体在线策略蒸馏的不确定性感知干预" aria-label="Permalink to &quot;🎯 UOPD：面向多轮智能体在线策略蒸馏的不确定性感知干预&quot;">​</a></h3><p><strong>UOPD: Uncertainty-Aware Intervention for On-Policy Distillation of Multi-Turn Agents</strong><em>arXiv (2026)</em></p><p>在线策略蒸馏（OPD）让学生在自身 rollout 上接受教师的稠密监督，但在多轮环境中，关键决策步的一次错误会把后续轨迹引向坏结果。作者以「教师对学生动作的低置信度」来挑选高不确定性步骤进行纠正：在受控 ALFWorld 实验中，在低置信步做一次教师纠正即可改善后续行为与任务成功率。据此提出 UOPD——低不确定性轮次执行学生动作并施加标准 OPD 损失，高不确定性轮次则采样并执行教师动作、用监督微调让学生模仿（期望上最小化前向 KL），并用自适应不确定性阈值把干预率控制在预定水平。在 ALFWorld、WebShop、Search 上优于 OPD 及其变体，WebShop 得分最高提升 15.8%。arXiv: <a href="https://arxiv.org/abs/2609.34036" target="_blank" rel="noreferrer">2609.34036</a></p><h3 id="🔁-r2flow-通过递归技能演化的递归自我改进" tabindex="-1">🔁 R²Flow：通过递归技能演化的递归自我改进 <a class="header-anchor" href="#🔁-r2flow-通过递归技能演化的递归自我改进" aria-label="Permalink to &quot;🔁 R²Flow：通过递归技能演化的递归自我改进&quot;">​</a></h3><p><strong>R² Flow: Recursive Self-Improvement via Recursive Skill Evolution</strong><em>arXiv (2026)</em></p><p>基于技能的智能体可通过复用与修订可执行程序来跨任务自我改进，流程式训练正契合这一循环，但有三重障碍：树状历史的策略坍塌、非负流程信用把「频繁使用」误当「有益」、以及技能库编辑只依赖策略自身优化的任务奖励。作者提出 R²Flow：在共享状态编排图上交替进行策略学习、独立验证与版本化技能库更新。该图把仅「独立步骤顺序不同」的历史合并，使流程训练能跨等价执行汇总证据；一个对后向策略不变的流程份额读出用于排序技能、独立验证证据决定是否值得修改、残差方差平台期决定何时更新。已提交的编辑会重塑下一轮策略所学的图，从而实现递归技能演化。arXiv: <a href="https://arxiv.org/abs/2609.33867" target="_blank" rel="noreferrer">2609.33867</a></p><h3 id="🍴-反事实轨迹重放-以可分叉环境作软件工程智能体的免费过程奖励" tabindex="-1">🍴 反事实轨迹重放：以可分叉环境作软件工程智能体的免费过程奖励 <a class="header-anchor" href="#🍴-反事实轨迹重放-以可分叉环境作软件工程智能体的免费过程奖励" aria-label="Permalink to &quot;🍴 反事实轨迹重放：以可分叉环境作软件工程智能体的免费过程奖励&quot;">​</a></h3><p><strong>Counterfactual Rollout Replay: Forkable Environments as Free Process Rewards for Software Engineering Agents</strong><em>arXiv (2026)</em></p><p>仅用结果信号的强化学习给软件工程（SWE）智能体一个终端成败信号，却对中间决策缺乏直接指引。作者提出反事实轨迹重放（CRR）：利用可分叉的可执行环境获得<strong>步级回报对比</strong>——选取少量决策点、恢复该状态、采样一个替代动作并在策略下向前 rollout；保留真实训练轨迹，把所选步的优势替换为「其终端回报与采样反事实回报之差」。方法无需人工过程标签或学得的过程奖励模型（「免费」指监督成本，而非重放算力）。用 14B 策略，CRR 在 SWE-bench Verified、Live、rebench 上提升 pass@1，并可与过程奖励/轨迹搜索方法组合；在等墙钟时间对比下，Verified 上 41.7% vs 仅结果 GRPO 的 36.7%，净增 5.0 分（已含分叉开销）。arXiv: <a href="https://arxiv.org/abs/2609.33875" target="_blank" rel="noreferrer">2609.33875</a></p><h3 id="🕸️-hypermcts-为长时程-llm-智能体的超图增强-mcts" tabindex="-1">🕸️ HyperMCTS：为长时程 LLM 智能体的超图增强 MCTS <a class="header-anchor" href="#🕸️-hypermcts-为长时程-llm-智能体的超图增强-mcts" aria-label="Permalink to &quot;🕸️ HyperMCTS：为长时程 LLM 智能体的超图增强 MCTS&quot;">​</a></h3><p><strong>HyperMCTS: Hypergraph-Augmented MCTS for Long-Horizon LLM Agents</strong><em>arXiv (2026)</em></p><p>长时程任务要求 LLM 智能体在贯穿整个解的约束下协调决策，MCTS 可借探索替代动作轨迹实现测试时扩展，但模型计算与环境交互使搜索代价高昂，故需高效复用轨迹反馈。标准 MCTS 只维护前缀特定的统计量，不显式累积「在不同路径上反复出现的决策组」的结果。作者提出免训练的 HyperMCTS：为有序 MCTS 树增设跨轨迹<strong>超图</strong>，超边表示一组规范决策并累积其在本任务内的观测回报；由超图引导的 HyperUCT 选择规则把重叠超边的证据聚合成动作先验，使在某一前缀下收集的结果能影响另一前缀的选择，同时在树中保留执行历史。在 DeepPlanning 上较最强基线提升 2.3–7.3 个百分点，使 Qwen3.6-27B 在 Shopping Planning 上超过 Claude Opus 4.6（max），且 LLM 调用与输出 token 更少。arXiv: <a href="https://arxiv.org/abs/2609.33920" target="_blank" rel="noreferrer">2609.33920</a></p><h3 id="🔓-当授权超出语境-长寿命智能体中的「残余权限重放」" tabindex="-1">🔓 当授权超出语境：长寿命智能体中的「残余权限重放」 <a class="header-anchor" href="#🔓-当授权超出语境-长寿命智能体中的「残余权限重放」" aria-label="Permalink to &quot;🔓 当授权超出语境：长寿命智能体中的「残余权限重放」&quot;">​</a></h3><p><strong>When Consent Outlives Context: Residual Authority Replay in Long-Lived Agents</strong><em>arXiv (2026)</em></p><p>LLM 智能体越来越多地依赖用户批准来在运行时授权安全敏感动作，这些批准是在特定任务与执行语境下给出的；而在长寿命智能体中，授权决策可能要跨任务或跨会话持续。作者发现这种延续性可能<strong>超出原本使批准正当化的语境</strong>，形成无需重新征得同意即可复用的「残余权限」。他们用纵向攻击暴露该失效模式：从目标敏感动作出发，识别执行它所需的权限，诱导一系列合规交互以合法获得该权限，随后在对抗执行中重放残余权限。在受控与真实环境中，残余权限重放显著提升提示注入与语境重绑定攻击的成功率：基于生产授权的语义对 6 个 LLM 家族的 508 个 AgentDojo 攻击用例，成功率较全新授权状态最高上升 35.1 个百分点；在 55 个 Terminal-Bench 用例、3 个真实生产编码智能体上的实时语境重绑定攻击中平均上升 24.9 个百分点。arXiv: <a href="https://arxiv.org/abs/2609.33910" target="_blank" rel="noreferrer">2609.33910</a></p><blockquote><p>📅 日期：2026-09-27 ｜ ⚠️ 事后重建版 ｜ 📂 科学前沿 5 篇 | 🤖 AI前沿 5 篇 期号：（第 ? 期 · 事后重建版）</p></blockquote>',35)])])}const m=r(n,[["render",s]]);export{p as __pageData,m as default};
